description:
{
  "image_category": "SIGN_ILLUSTRATION",
  "summary": "Hình ảnh minh họa ba biển báo giao thông số I.433b, I.433c và I.433d theo QCVN 41:2024/BGTVT, dùng để chỉ dẫn nơi cắm trại, nhà nghỉ lưu động hoặc cả hai trên các tuyến đường đối ngoại.",
  "items": [
    {
      "identifier": "Biển số I.433b",
      "visual_or_geometric_features": "Hình chữ nhật đứng, nền xanh dương, viền trắng; bên trong là hình tam giác đen (mũi tên hướng lên trên) biểu tượng cho nơi cắm trại.",
      "meaning_or_specification": "Chỉ dẫn sắp đến nơi có vị trí cắm trại, đặt trên các tuyến đường đối ngoại và tuyến đường có nhiều người nước ngoài đi lại."
    },
    {
      "identifier": "Biển số I.433c",
      "visual_or_geometric_features": "Hình chữ nhật đứng, nền xanh dương, viền trắng; bên trong là hình ảnh nhà lưu động (xe nhà) màu đen.",
      "meaning_or_specification": "Chỉ dẫn sắp đến nơi dành cho nhà lưu động, đặt trên các tuyến đường đối ngoại và tuyến đường có nhiều người nước ngoài đi lại."
    },
    {
      "identifier": "Biển số I.433d",
      "visual_or_geometric_features": "Hình chữ nhật đứng, nền xanh dương, viền trắng; bên trong là hai biểu tượng xếp chồng: hình tam giác đen (nơi cắm trại) ở trên và hình nhà lưu động màu đen ở dưới.",
      "meaning_or_specification": "Chỉ dẫn sắp đến nơi có cả vị trí cắm trại và nhà lưu động, đặt trên các tuyến đường đối ngoại và tuyến đường có nhiều người nước ngoài đi lại."
    }
  ]
}
